-- Make the server authoritative for every custom skill-book title and
-- description. The migration is intentionally idempotent.
-- Each skill gets its own display-only shop option, matching the existing
-- Khí Nguyên Trảm books.  The options have no gameplay effect: they only make
-- the shop line unambiguous and leave the book's actual level in its template.

START TRANSACTION;

UPDATE `skill_template`
SET
    `NAME` = CONVERT(0x4CE1BBB17520C490E1BAA16E20C490E1BB8B61204E67E1BBA563 USING utf8mb4),
    `skills` = CONVERT( USING utf8mb4)
WHERE `nclass_id` = 1 AND `id` = 28;

UPDATE `skill_template`
SET
    `NAME` = CONVERT(0x4E67E1BBA563204769616D204CC3A1204368E1BAAF6E USING utf8mb4),
    `skills` = CONVERT( USING utf8mb4)
WHERE `nclass_id` = 0 AND `id` = 29;

UPDATE `item_template`
SET
    `NAME` = CONCAT(CONVERT(0x53C3A16368204B68C3AD204E677579C3AA6E205472E1BAA36D2063E1BAA57020 USING utf8mb4), `id` - 2218),
    `description` = CASE
        WHEN `id` = 2219 THEN CONVERT(0x44C3B96E6720C491E1BB832068E1BB8D63204B68C3AD204E677579C3AA6E205472E1BAA36D2063E1BAA57020312E USING utf8mb4)
        ELSE CONCAT(CONVERT(0x44C3B96E6720C491E1BB83206EC3A26E67204B68C3AD204E677579C3AA6E205472E1BAA36D206CC3AA6E2063E1BAA57020 USING utf8mb4), `id` - 2218, '.')
    END
WHERE `id` BETWEEN 2219 AND 2225;

UPDATE `item_template`
SET
    `NAME` = CONCAT(CONVERT(0x53C3A16368204CE1BBB17520C490E1BAA16E20C490E1BB8B61204E67E1BBA5632063E1BAA57020 USING utf8mb4), `id` - 2225),
    `description` = CASE
        WHEN `id` = 2226 THEN CONVERT(0x44C3B96E6720C491E1BB832068E1BB8D63204CE1BBB17520C490E1BAA16E20C490E1BB8B61204E67E1BBA5632063E1BAA57020312E USING utf8mb4)
        ELSE CONCAT(CONVERT(0x44C3B96E6720C491E1BB83206EC3A26E67204CE1BBB17520C490E1BAA16E20C490E1BB8B61204E67E1BBA563206CC3AA6E2063E1BAA57020 USING utf8mb4), `id` - 2225, '.')
    END
WHERE `id` BETWEEN 2226 AND 2232;

UPDATE `item_template`
SET
    `NAME` = CONCAT(CONVERT(0x53C3A16368204E67E1BBA563204769616D204CC3A1204368E1BAAF6E2063E1BAA57020 USING utf8mb4), `id` - 2232),
    `description` = CASE
        WHEN `id` = 2233 THEN CONVERT(0x44C3B96E6720C491E1BB832068E1BB8D63204E67E1BBA563204769616D204CC3A1204368E1BAAF6E2063E1BAA57020312E USING utf8mb4)
        ELSE CONCAT(CONVERT(0x44C3B96E6720C491E1BB83206EC3A26E67204E67E1BBA563204769616D204CC3A1204368E1BAAF6E206CC3AA6E2063E1BAA57020 USING utf8mb4), `id` - 2232, '.')
    END
WHERE `id` BETWEEN 2233 AND 2239;

INSERT INTO `item_option_template` (`id`, `NAME`)
VALUES
    (253, CONVERT(0x4CE1BBB17520C490E1BAA16E20C490E1BB8B61204E67E1BBA5632063E1BAA5702023 USING utf8mb4)),
    (254, CONVERT(0x4E67E1BBA563204769616D204CC3A1204368E1BAAF6E2063E1BAA5702023 USING utf8mb4))
ON DUPLICATE KEY UPDATE `NAME` = VALUES(`NAME`);

DELETE `item_shop_option`
FROM `item_shop_option`
INNER JOIN `item_shop` ON `item_shop`.`id` = `item_shop_option`.`item_shop_id`
WHERE `item_shop`.`tab_id` = 11
  AND `item_shop`.`temp_id` BETWEEN 2226 AND 2239
  AND `item_shop_option`.`option_id` IN (72, 253, 254);

INSERT INTO `item_shop_option` (`item_shop_id`, `option_id`, `param`)
SELECT
    `id`,
    CASE
        WHEN `temp_id` BETWEEN 2226 AND 2232 THEN 253
        ELSE 254
    END,
    CASE
        WHEN `temp_id` BETWEEN 2226 AND 2232 THEN `temp_id` - 2225
        ELSE `temp_id` - 2232
    END
FROM `item_shop`
WHERE `tab_id` = 11 AND `temp_id` BETWEEN 2226 AND 2239;

COMMIT;
